func updateTargetsMap(slot uint32, fd int) error {
	m, err := ebpf.LoadPinnedMap(targetMapPath(), nil)
	if err != nil {
		return fmt.Errorf("load target map: %w", err)
	}
	defer m.Close()

	value := uint32(fd)
	if err := m.Update(&slot, &value, ebpf.UpdateAny); err != nil {
		return fmt.Errorf("update target map: %w", err)
	}
	return nil
}

func clearTargets(numSlots int) error {
	m, err := ebpf.LoadPinnedMap(targetMapPath(), nil)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return nil
		}
		return err
	}
	defer m.Close()

	for i := 0; i < numSlots; i++ {
		key := uint32(i)
		if err := m.Delete(&key); err != nil && !errors.Is(err, ebpf.ErrKeyNotExist) {
			return fmt.Errorf("clear slot %d: %w", i, err)
		}
	}
	return nil
}

func loadAgent(workers int) (*ebpfPolicy, error) {
	...
	var key uint32 = 0
	state := ebpfutil.AgentSelectorAgentState{
		Active: uint32(workers),
	}
	if objs.PebbleAgentState != nil {
		if err := objs.PebbleAgentState.Update(&key, &state, ebpf.UpdateAny); err != nil {
			objs.Close()
			return nil, fmt.Errorf("configure agent state: %w", err)
		}
	}

	return &ebpfPolicy{
		name:    "agent",
		program: objs.AgentUdpSelector,
		close:   objs.Close,
	}, nil
}

struct agent_state {
    __u32 active;
    __u32 pad;
};

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, struct agent_state);
    __uint(pinning, LIBBPF_PIN_BY_NAME);
} pebble_agent_state SEC(".maps");

SEC("sk_reuseport/selector")
enum sk_action agent_udp_selector(struct sk_reuseport_md *reuse)
{
    __u32 key = 0;
    struct agent_state *state = bpf_map_lookup_elem(&pebble_agent_state, &key);
    if (!state || state->active == 0)
        return SK_PASS;

    __u32 start = reuse->hash % state->active;
    ...
        if (slot >= state->active)
            slot -= state->active;
    ...
}

func (s *Server) openWorker(idx int) (*net.UDPConn, int, error) {
	attachPolicy := s.policy != nil && s.policy.program != nil && idx == 0
	var attachErr error

	lc := net.ListenConfig{Control: func(network, address string, c syscall.RawConn) error {
		return c.Control(func(fd uintptr) {
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEADDR, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEADDR: %w", err)
				return
			}
			if err := unix.SetsockoptInt(int(fd), unix.SOL_SOCKET, unix.SO_REUSEPORT, 1); err != nil && attachErr == nil {
				attachErr = fmt.Errorf("SO_REUSEPORT: %w", err)
				return
			}
			if attachPolicy && attachErr == nil {
				if err := s.policy.attach(int(fd)); err != nil {
					attachErr = err
				}
			}
		})
	}}

func (s *Server) Run(ctx context.Context) error {
	...
	for i := 0; i < s.cfg.Workers; i++ {
		conn, fd, err := s.openWorker(i)
		if err != nil {
			return fmt.Errorf("open worker %d: %w", i, err)
		}

		if s.policy != nil && s.policy.program != nil {
			if err := updateTargetsMap(uint32(i), fd); err != nil {
				conn.Close()
				return fmt.Errorf("update reuseport map: %w", err)
			}
		}

		s.conns = append(s.conns, conn)
		s.spawnWorker(ctx, i, conn)
	}
	...
}
